use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut total_time = 0;
    for item in data {
        let arrival = item[0].as_i64().unwrap();
        let duration = item[1].as_i64().unwrap();
        total_time += arrival + duration;
    }
    Value::Number(total_time as f64)
}
